-- Migration 054: Seed Cecistas (personas + modos + vínculo a fraternidad)
-- Source: "Cecistas - Cecistas.csv"
-- Depends on: 011 (personas.nombre_usuario), 034 (personas.tipo_persona),
--             050 (personas.codigo_interno + uq_personas_codigo_interno),
--             043 (organizaciones con codigo CONF-*/FRAT-* para resolver el vínculo).
-- Run this in the Supabase SQL editor. (Si aparece el aviso de RLS por la tabla
-- temporal _stg_cec -> "Run without RLS": es de sesión y se descarta en COMMIT.)
--
-- Comportamiento (acordado con el usuario):
--   * UPSERT de personas por codigo_interno (CCD-#####). Las personas existentes SIN
--     ese codigo NO se tocan (tu cuenta y usuarios de prueba quedan intactos).
--   * tipo_persona='cecista'. nombre_usuario se guarda como dato (los LOGINS reales
--     se crean aparte via API de Auth; este script no crea accesos).
--   * persona_modos y persona_organizacion se REEMPLAZAN solo para las personas
--     importadas (delete+insert acotado por codigo_interno) -> re-ejecutable.
--   * Filas basura del CSV (#VALUE!/#N/A) se ignoran. Username duplicado ('enacuba')
--     se deduplica (se conserva en la primera, NULL en la repetida).
--   * Códigos de org con error de planilla (#REF!/#N/A) no resuelven -> ese vínculo
--     se omite (el resto de la persona se importa igual).

BEGIN;

CREATE TEMP TABLE _stg_cec (
  codigo_interno TEXT PRIMARY KEY,
  nombre         TEXT NOT NULL,
  apellido       TEXT NOT NULL,
  nombre_usuario TEXT,
  modo           TEXT,
  conf_codigo    TEXT,
  frat_codigo    TEXT
) ON COMMIT DROP;

