-- ─── 1. Upsert personas por codigo_interno ────────────────────────────────────
INSERT INTO public.personas (codigo_interno, nombre, apellido, nombre_usuario, tipo_persona, estado)
SELECT codigo_interno, nombre, apellido, nombre_usuario, 'cecista', 'activo'
  FROM _stg_cec
ON CONFLICT (codigo_interno) WHERE codigo_interno IS NOT NULL DO UPDATE
  SET nombre         = EXCLUDED.nombre,
      apellido       = EXCLUDED.apellido,
      nombre_usuario = COALESCE(EXCLUDED.nombre_usuario, public.personas.nombre_usuario),
      tipo_persona   = 'cecista',
      updated_at     = now();

-- ─── 2. Reemplazar modos y vínculos de org SOLO para las importadas ───────────
DELETE FROM public.persona_modos
  WHERE persona_id IN (SELECT p.id FROM public.personas p JOIN _stg_cec s ON s.codigo_interno = p.codigo_interno);

DELETE FROM public.persona_organizacion
  WHERE persona_id IN (SELECT p.id FROM public.personas p JOIN _stg_cec s ON s.codigo_interno = p.codigo_interno);

-- Modo de participación
INSERT INTO public.persona_modos (persona_id, modo, fecha_inicio, estado)
SELECT p.id, s.modo, CURRENT_DATE, 'activo'
  FROM _stg_cec s
  JOIN public.personas p ON p.codigo_interno = s.codigo_interno
  WHERE s.modo IS NOT NULL;

-- Vínculo a confraternidad
INSERT INTO public.persona_organizacion (persona_id, organizacion_id, tipo_relacion, fecha_inicio)
SELECT p.id, o.id, 'confraternidad', CURRENT_DATE
  FROM _stg_cec s
  JOIN public.personas p    ON p.codigo_interno = s.codigo_interno
  JOIN public.organizaciones o ON o.codigo = s.conf_codigo AND o.tipo = 'confraternidad'
  WHERE s.conf_codigo IS NOT NULL;

-- Vínculo a fraternidad
INSERT INTO public.persona_organizacion (persona_id, organizacion_id, tipo_relacion, fecha_inicio)
SELECT p.id, o.id, 'fraternidad', CURRENT_DATE
  FROM _stg_cec s
  JOIN public.personas p    ON p.codigo_interno = s.codigo_interno
  JOIN public.organizaciones o ON o.codigo = s.frat_codigo AND o.tipo = 'fraternidad'
  WHERE s.frat_codigo IS NOT NULL;

COMMIT;

